head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[Submission > P > userData2]<br/>미리 정의된 사용자 정의 속성으로서 필요에 따라 사용자 데이터를 자유롭게 설정합니다.",
    "validation" : [
        "Submission 컴포넌트에서 사용할 사용자 데이터를 문자열로 설정할 수 있어야 합니다."
    ]
}



scwin.onpageload = function () {
    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    scwin.comp_init();
};



// comp 생성 (Submission 은 화면에 표시되지 않으므로 grp_comp 에는 안내 라벨만 생성)
scwin.comp_init = async function () {
    if (typeof label1 !== 'undefined') {
        label1.remove();
    }

    $c.gcm.createLabel('label="Submission 은 화면에 표시되지 않는 컴포넌트입니다.\n[절차] userData2 입력 -> Target 재생성\n[확인] userData2 확인 버튼으로 Submission 에 설정된 userData2 값 확인"', '', 'label1');

    // 조건 설정 (빈값이면 속성 미설정)
    let sInfo = {};
    let cUserData = con_userData2.getValue();

    if (cUserData !== "") {
        sInfo.userData2 = cUserData;
    }

    // comp 생성 (동일 ID 는 createSubmission 이 기존 것을 교체)
    scwin.target1 = await $c.gcm.createBasicSubmission(sInfo, "target1");
};



// validation 1 판정 출력 : Submission 에 설정된 userData2 값
scwin.btn_getUserData_onclick = function (e) {
    let objSubmission = $p.getSubmission("target1");

    wf_body_bottom.getObj("scwin").setReturnValue("userData2 : " + (objSubmission ? objSubmission.userData2 : objSubmission));
};
